export const GENERATED_CONFIG_PATH = 'config.local.js';
export const GENERATED_CONFIG_CONTENT = [
  '// Generated by scripts/package-release.mjs for store builds.',
  'window.SPACE_TABS_CONFIG = window.SPACE_TABS_CONFIG || {};',
  '',
].join('\n');

// Store packages are intentionally assembled from individual runtime files.
// Adding a new runtime module requires an explicit review and an entry here.
export const RUNTIME_FILES = Object.freeze([
  'manifest.json',
  'background.js',
  'sidepanel.html',
  'sidepanel.css',
  'sidepanel.js',
  'src/shared/ai-providers.js',
  'src/shared/ai.js',
  'src/shared/arc-file-access.js',
  'src/shared/arc-import.js',
  'src/shared/ask-session.js',
  'src/shared/ask-sources.js',
  'src/shared/command-palette.js',
  'src/shared/folder-tree.js',
  'src/shared/markdown.js',
  'src/shared/operation-safety.js',
  'src/shared/organization-plan.js',
  'src/shared/preview-runtime.js',
  'src/shared/shortcuts.js',
  'src/shared/space-membership.js',
  'src/shared/space-snapshot.js',
  'src/shared/space-transfer.js',
  'src/shared/state.js',
  'src/shared/tab-selection.js',
  'src/shared/tab-utils.js',
  'icons/icon16.png',
  'icons/icon32.png',
  'icons/icon48.png',
  'icons/icon128.png',
]);

export const RELEASE_FILES = Object.freeze([
  ...RUNTIME_FILES,
  GENERATED_CONFIG_PATH,
]);

const SECRET_PATTERNS = [
  ['private key', /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/],
  ['OpenAI-style API key', /\bsk-(?:proj-|live-)?[A-Za-z0-9_-]{16,}\b/],
  ['Google API key', /\bAIza[0-9A-Za-z_-]{30,}\b/],
  ['GitHub token', /\bgh[pousr]_[A-Za-z0-9]{20,}\b/],
  ['Slack token', /\bxox[baprs]-[0-9A-Za-z-]{20,}\b/],
  ['AWS access key', /\bAKIA[0-9A-Z]{16}\b/],
  [
    'assigned credential',
    /\b(?:api[_-]?key|access[_-]?token|client[_-]?secret|password)\s*[:=]\s*['"`]([^'"`\r\n]{8,})['"`]/i,
  ],
];

export function assertSafeReleaseEntries(entries, expectedEntries = RELEASE_FILES) {
  if (!Array.isArray(entries)) throw new Error('Release entries must be an array.');
  const normalized = entries.map((entry) => String(entry));
  const duplicates = normalized.filter((entry, index) => normalized.indexOf(entry) !== index);
  if (duplicates.length > 0) {
    throw new Error(`Duplicate release entry: ${[...new Set(duplicates)].join(', ')}`);
  }

  for (const entry of normalized) assertSafeReleasePath(entry);

  const expected = [...expectedEntries].sort();
  const actual = [...normalized].sort();
  const missing = expected.filter((entry) => !actual.includes(entry));
  const unexpected = actual.filter((entry) => !expected.includes(entry));
  if (missing.length > 0 || unexpected.length > 0) {
    const details = [
      missing.length > 0 ? `missing: ${missing.join(', ')}` : '',
      unexpected.length > 0 ? `unexpected: ${unexpected.join(', ')}` : '',
    ].filter(Boolean).join('; ');
    throw new Error(`Release archive does not match the runtime allowlist (${details}).`);
  }
}

export function assertSafeReleasePath(entry) {
  if (!entry || entry.startsWith('/') || entry.endsWith('/') || entry.includes('\\')) {
    throw new Error(`Unsafe release entry: ${entry || '(empty)'}`);
  }
  const segments = entry.split('/');
  if (segments.some((segment) => !segment || segment === '.' || segment === '..' || segment.startsWith('.'))) {
    throw new Error(`Hidden or non-canonical release entry: ${entry}`);
  }
  const basename = segments.at(-1);
  if (/\.map$/i.test(basename)) throw new Error(`Source maps are not allowed in release packages: ${entry}`);
  if (/(?:^|\.)(?:test|spec)\.[^.]+$/i.test(basename) || segments.includes('__tests__')) {
    throw new Error(`Test files are not allowed in release packages: ${entry}`);
  }
  if (
    /(?:secret|credential|private[-_]?key)/i.test(basename) ||
    /^\.env/i.test(basename) ||
    (/config/i.test(basename) && entry !== GENERATED_CONFIG_PATH)
  ) {
    throw new Error(`Sensitive config is not allowed in release packages: ${entry}`);
  }
}

export function findSecret(text) {
  const source = String(text || '');
  for (const [label, pattern] of SECRET_PATTERNS) {
    if (pattern.test(source)) return label;
  }
  return '';
}

export function assertArchiveHasNoSymlinks(verboseListing) {
  if (/^l[rwx-]{9}\s/m.test(String(verboseListing || ''))) {
    throw new Error('Release archive contains a symbolic link.');
  }
}
